    private boolean isTimeAccurateThroughRoom(TOBRoom room)
    {
        switch (room)
        {
            case VERZIK:
                if (!verzikTimeAccurate)
                {
                    return false;
                }
            case XARPUS:
                if (!xarpTimeAccurate)
                {
                    return false;
                }
            case SOTETSEG:
                if (!soteTimeAccurate)
                {
                    return false;
                }
            case NYLOCAS:
                if (!nyloTimeAccurate)
                {
                    return false;
                }
            case BLOAT:
                if (!bloatTimeAccurate)
                {
                    return false;
                }
            case MAIDEN:
                return maidenTimeAccurate;
        }
        return false;
    }

